16	#ifndef FLASH_ATTENTION_SCORE_ENHANCE_PSE_H
17	#define FLASH_ATTENTION_SCORE_ENHANCE_PSE_H
18	
19	#include "kernel_operator.h"
20	#include "util.h"
21	
22	constexpr static int64_t pseS1S2 = 0;
23	constexpr static int64_t pse1S2 = 1;
24	constexpr static int64_t PSE_SLOPE_BN = 2;
25	constexpr static int64_t PSE_SLOPE_N = 3;
26	
27	constexpr static uint8_t pseEncodeALibiS2Full = 0x11;
28	
29	enum class PseTypeEnum {
30	    PSE_OUTER_MUL_ADD_TYPE = 0, // default
31	    PSE_OUTER_ADD_MUL_TYPE,
32	    PSE_INNER_MUL_ADD_TYPE,
33	    PSE_INNER_MUL_ADD_SQRT_TYPE,
34	    PSE_INVALID_TYPE
35	};
36	
37	struct PseInfo {
38	    int64_t blockCount;
39	    int64_t bSSOffset; // boidx * s1 * s2
40	    int64_t boIdx;
41	    int64_t gSize;
42	    int64_t goIdx;
43	    int64_t loopIdx;
44	    int64_t n2G;
45	    int64_t n2oIdx;
46	    int64_t pseBSize;
47	    int64_t pseS1Size;        // for alibi
48	    int64_t pseS2ComputeSize; // for alibi, do not need assignment
49	    int64_t pseS2Size;        // for alibi
50	    uint32_t pseShapeType;
51	    int64_t readS2Size; // for alibi, do not need assignment
52	    int64_t s1BaseSize;
53	    int64_t s1Size;
54	    int64_t s1oIdx;
55	    int64_t s2AlignedSize;
56	    int64_t s2BaseNratioSize;
57	    int64_t s2LoopCount;
58	    int64_t s2RealSize;
59	    int64_t s2Size;
60	    int64_t s2SizeAcc; // accumulated sum of s2 size
61	    int64_t s2StartIdx;
62	    int64_t vec1S1BaseSize;
63	    int64_t vec1S1RealSize;
64	    uint32_t pseEncodeType; // for distinguish alibi
65	    uint32_t pseType; // 0: outer, mul-add   1:outer, add-mul   2:inner, mul-add   3:inner, mul-add-sqrt
66	    int64_t pseAlibiBaseS1;
67	    int64_t pseAlibiBaseS2;
68	    int64_t qStartIdx;
69	    int64_t kvStartIdx;
70	    int64_t vecCoreOffset = 0;
71	    bool needCast;
72	    bool align8 = false;
73	    bool pseEndogenous = false;
74	};
75	
76	template <typename INPUT_T, bool hasPse>
77	__aicore__ inline void DataCopyInCommon(LocalTensor<INPUT_T> &dstTensor, GlobalTensor<INPUT_T> &srcTensor, 
78	                                  int64_t offset, int64_t s1Size, int64_t s2Size, 
79	                                  int64_t actualS2Len, int32_t dtypeSize, int32_t alignedS2Size)
80	{
81	    if constexpr (hasPse == true) {
82	        uint32_t shapeArray[] = {static_cast<uint32_t>(s1Size), static_cast<uint32_t>(alignedS2Size)};
83	        dstTensor.SetShapeInfo(ShapeInfo(2, shapeArray, DataFormat::ND));
84	        dstTensor.SetSize(s1Size * alignedS2Size);
85	        DataCopyParams dataCopyParams;
86	        dataCopyParams.blockCount = s1Size;
87	        dataCopyParams.blockLen = CeilDiv(s2Size * dtypeSize, blockBytes); // 单位32B
88	        dataCopyParams.dstStride = 
89	                alignedS2Size * dtypeSize / blockBytes - dataCopyParams.blockLen; // gap
90	        if (actualS2Len * dtypeSize % blockBytes == 0) {
91	            dataCopyParams.srcStride =
92	                (actualS2Len * dtypeSize - dataCopyParams.blockLen * blockBytes) / blockBytes; // srcGap
93	            DataCopy(dstTensor, srcTensor[offset], dataCopyParams);
94	        } else {
95	            dataCopyParams.blockLen = s2Size * dtypeSize; // 单位Byte
96	            dataCopyParams.srcStride = (actualS2Len * dtypeSize - dataCopyParams.blockLen);
97	            dataCopyParams.dstStride = (alignedS2Size - s2Size) * dtypeSize / blockBytes;
98	            DataCopyPadParams dataCopyPadParams;
99	            dataCopyPadParams.isPad = false;
100	            DataCopyPad(dstTensor, srcTensor[offset], dataCopyParams, dataCopyPadParams);
101	        }
102	    }
103	}
104	
105	template <typename INPUT_T, bool hasPse>
106	__aicore__ inline void DataCopyIn(LocalTensor<INPUT_T> &dstTensor, GlobalTensor<INPUT_T> &srcTensor, int64_t offset,
107	                                  int64_t s1Size, int64_t s2Size, int64_t actualS2Len, int64_t alignedSize = 16)
108	{
109	    if constexpr (hasPse == true) {
110	        int32_t dtypeSize = sizeof(INPUT_T);
111	        int32_t alignedS2Size = CeilDiv(s2Size, alignedSize) * alignedSize;
112	        DataCopyInCommon<INPUT_T, hasPse>(dstTensor, srcTensor, offset, s1Size, s2Size,
113	            actualS2Len, dtypeSize, alignedS2Size);
114	    }
115	}
