117	template <typename INPUT_T, bool hasPse>
118	__aicore__ inline void DataCopyInAlign8(LocalTensor<INPUT_T> &dstTensor, GlobalTensor<INPUT_T> &srcTensor, 
119	                                        int64_t offset, int64_t s1Size, 
120	                                        int64_t s2Size, int64_t actualS2Len)
121	{
122	    if constexpr (hasPse == true) {
123	        int32_t dtypeSize = sizeof(INPUT_T);
124	        if (dtypeSize == 0){
125	            return;
126	        }
127	        int32_t alignedS2Size = CeilDiv(s2Size, 32 / dtypeSize) * (32 / dtypeSize);
128	        DataCopyInCommon<INPUT_T, hasPse>(dstTensor, srcTensor, offset, s1Size, s2Size,
129	            actualS2Len, dtypeSize, alignedS2Size);
130	    }
131	}
