133	/*
134	dst = BroadcastAdd(src0, src1)
135	src0 shape: (s1, s2)
136	src1 shape: (1, s2)
137	dst  shape: (s1, s2)
138	*/
139	template <typename T, bool hasPse>
140	__aicore__ inline void BroadcastAdd(const LocalTensor<T> &src0Tensor, const LocalTensor<T> &src1Tensor,
141	                                    int64_t src0Offset, int32_t src1Size, int32_t repeatTimes)
142	{
143	    if constexpr (hasPse == true) {
144	        /* Total data number of single step should be smaller than 256bytes.
145	         * If larger, we need to do add multiple times. */
146	        int32_t innerLoop = src1Size / repeatMaxSize;   // s2轴整块计算次数
147	        int32_t innerRemain = src1Size % repeatMaxSize; // s2轴尾块计算量
148	        BinaryRepeatParams binaryRepeatParams;
149	        binaryRepeatParams.src0BlkStride = 1;
150	        binaryRepeatParams.src0RepStride = src1Size / blockSize;
151	        binaryRepeatParams.src1BlkStride = 1;
152	        binaryRepeatParams.src1RepStride = 0;
153	        binaryRepeatParams.dstRepStride = binaryRepeatParams.src0RepStride;
154	        binaryRepeatParams.blockNumber = binaryRepeatParams.src0RepStride;
155	
156	        for (int32_t j = 0; j < innerLoop; j++) {
157	            auto innerOffset = j * repeatMaxSize;
158	            auto ubOffset = src0Offset + innerOffset;
159	            Add(src0Tensor[ubOffset], src0Tensor[ubOffset], src1Tensor[innerOffset], repeatMaxSize, repeatTimes,
160	                binaryRepeatParams);
161	        }
162	        if (innerRemain > 0) {
163	            auto innerOffset = innerLoop * repeatMaxSize;
164	            auto ubOffset = src0Offset + innerOffset;
165	            Add(src0Tensor[ubOffset], src0Tensor[ubOffset], src1Tensor[innerOffset], innerRemain, repeatTimes,
166	                binaryRepeatParams);
167	        }
168	    }
169	}
170	
171	template <typename T, bool hasPse>
172	__aicore__ inline void PseBroadcastAdd(int32_t s1Size, int32_t s2Size, int32_t computeSize, const LocalTensor<T> &pseUb,
173	                                       const LocalTensor<T> &dstTensor, uint32_t pseShapeType)
174	{
175	    if constexpr (hasPse == true) {
176	        if (pseShapeType == pseS1S2 || pseShapeType == PSE_SLOPE_BN || pseShapeType == PSE_SLOPE_N) {
177	            Add(dstTensor, dstTensor, pseUb, computeSize);
178	        } else {
179	            /* Total repeated times should be <= repeatMaxTimes. If larger,
180	             * we need to do multiple inner loops. */
181	            int32_t s1OuterLoop = s1Size / repeatMaxTimes;
182	            int32_t s1OuterRemain = s1Size % repeatMaxTimes;
183	            for (int32_t s1OuterIdx = 0; s1OuterIdx < s1OuterLoop; s1OuterIdx++) {
184	                int32_t s1OuterOffset = s1OuterIdx * repeatMaxTimes * s2Size;
185	                BroadcastAdd<T, hasPse>(dstTensor, pseUb, s1OuterOffset, s2Size, repeatMaxTimes);
186	            }
187	            if (s1OuterRemain > 0) {
188	                int32_t s1OuterOffset = s1OuterLoop * repeatMaxTimes * s2Size;
189	                BroadcastAdd<T, hasPse>(dstTensor, pseUb, s1OuterOffset, s2Size, s1OuterRemain);
190	            }
191	        }
192	    }
193	}
194	template <bool hasPse> __aicore__ inline int64_t PseComputeOffset(PseInfo &pseInfo)
195	{
196	    if constexpr (hasPse == true) {
197	        int64_t bOffset = 0;
198	        int64_t n2Offset = 0;
199	        int64_t s1Offset = 0;
200	        int64_t s2Offset = pseInfo.s2StartIdx + pseInfo.s2LoopCount * pseInfo.s2BaseNratioSize;
201	        int64_t gOffset = 0;
202	        if (pseInfo.pseShapeType == pseS1S2) {
203	            // b, n2, g, s1, s2
204	            bOffset = pseInfo.bSSOffset * pseInfo.n2G;
205	            n2Offset = pseInfo.n2oIdx * pseInfo.gSize * pseInfo.s1Size * pseInfo.s2Size;
206	            gOffset = pseInfo.goIdx * pseInfo.s1Size * pseInfo.s2Size;
207	            s1Offset = (pseInfo.s1oIdx * pseInfo.s1BaseSize + pseInfo.vecCoreOffset +
208	                       pseInfo.loopIdx * pseInfo.vec1S1BaseSize) * pseInfo.s2Size;
209	        } else if (pseInfo.pseShapeType == pse1S2) {
210	            // b, n2, g, 1, s2
211	            bOffset = pseInfo.s2SizeAcc * pseInfo.n2G;
212	            n2Offset = pseInfo.n2oIdx * pseInfo.gSize * pseInfo.s2Size;
213	            gOffset = pseInfo.goIdx * pseInfo.s2Size;
214	        }
215	        if (pseInfo.pseBSize == 1) {
216	            bOffset = 0;
217	        }
218	        return bOffset + n2Offset + gOffset + s1Offset + s2Offset;
219	    } else {
220	        return 0;
221	    }
222	}
223	
224	template <LayOutTypeEnum layOutType, bool hasPse> __aicore__ inline int64_t PseAlibiComputeOffset(PseInfo &pseInfo)
225	{
226	    if constexpr (hasPse == true) {
227	        int64_t bOffset = (pseInfo.boIdx % pseInfo.pseBSize) * pseInfo.n2G * pseInfo.pseS2Size * pseInfo.pseS1Size;
228	        int64_t n2Offset = pseInfo.n2oIdx * pseInfo.gSize * pseInfo.pseS2Size * pseInfo.pseS1Size;
229	        int64_t gOffset = pseInfo.goIdx * pseInfo.pseS2Size * pseInfo.pseS1Size;
230	        int64_t row = pseInfo.s1oIdx * pseInfo.s1BaseSize + pseInfo.vecCoreOffset +
231	                      pseInfo.loopIdx * pseInfo.vec1S1BaseSize;
232	        int64_t column = pseInfo.s2StartIdx + pseInfo.s2LoopCount * pseInfo.s2BaseNratioSize;
233	        int64_t m = 0;
234	        int64_t k = 0;
235	        if constexpr (layOutType != LayOutTypeEnum::LAYOUT_TND) {
236	            int64_t threshold = pseInfo.s1Size - pseInfo.pseS1Size;
237	            if (row >= threshold) {
238	                m = row - threshold;
239	                k = column;
240	            } else {
241	                m = row % pseInfo.pseS1Size;
242	                k = pseInfo.pseS2Size - (row - column) - (pseInfo.pseS1Size - m);
243	            }
244	        } else {
245	            int64_t threshold = pseInfo.pseS2Size - pseInfo.pseS1Size;
246	            int64_t posVal = row - column - threshold;
247	            if (threshold >= 0) {
248	                if (posVal >= 0) {
249	                    m = posVal;
250	                    k = 0;
251	                } else {
252	                    m = 0;
253	                    k = -posVal;
254	                }
255	            } else {
256	                m = posVal;
257	                k = 0;
258	            }
259	        }
260	        int64_t s1Offset = m * pseInfo.pseS2Size;
261	        int64_t s2Offset = k;
262	        pseInfo.readS2Size = Min(pseInfo.s2AlignedSize, pseInfo.pseS2Size - k);
263	        pseInfo.pseS2ComputeSize = Align(pseInfo.readS2Size);
264	
265	        return bOffset + n2Offset + gOffset + s1Offset + s2Offset;
266	    } else {
267	        return 0;
268	    }
269	}
270	
271	template <bool hasPse> __aicore__ inline bool NeedPseAlibiCompute(PseInfo &pseInfo)
272	{
273	    if constexpr (hasPse == true) {
274	        // Alibi编码只计算下三角
275	        if (pseInfo.s1oIdx * pseInfo.s1BaseSize + pseInfo.vecCoreOffset +
276	            (pseInfo.loopIdx + 1) * pseInfo.vec1S1BaseSize <=
277	            pseInfo.s2StartIdx + pseInfo.s2LoopCount * pseInfo.s2BaseNratioSize) {
278	            return false;
279	        }
280	        return true;
281	    } else {
282	        return false;
283	    }
284	}
