286	template <typename INPUT_T, typename T, LayOutTypeEnum layOutType, bool hasPse>
287	__aicore__ inline void PseAlibiCopyIn(LocalTensor<T> &dstTensor, LocalTensor<INPUT_T> &tmpTensor,
288	                                      GlobalTensor<INPUT_T> &srcTensor, PseInfo &pseInfo, int64_t alignedSize = 16)
289	{
290	    if constexpr (hasPse == true) {
291	        if (!NeedPseAlibiCompute<hasPse>(pseInfo)) {
292	            return;
293	        }
294	        int64_t offset = PseAlibiComputeOffset<layOutType, hasPse>(pseInfo);
295	        if constexpr (IsSameType<INPUT_T, T>::value) {
296	            if (!pseInfo.align8){
297	                DataCopyIn<INPUT_T, hasPse>(dstTensor, srcTensor, offset, pseInfo.vec1S1RealSize, pseInfo.readS2Size,
298	                                        pseInfo.pseS2Size, alignedSize);
299	            } else {
300	                DataCopyInAlign8<INPUT_T, hasPse>(dstTensor, srcTensor, offset, pseInfo.vec1S1RealSize,
301	                        pseInfo.readS2Size, pseInfo.pseS2Size);
302	            }
303	            return;
304	        }
305	
306	        DataCopyIn<INPUT_T, hasPse>(tmpTensor, srcTensor, offset, pseInfo.vec1S1RealSize, pseInfo.readS2Size,
307	                                    pseInfo.pseS2Size, alignedSize);
308	        if (pseInfo.needCast) {
309	            event_t eventIdMte2ToV = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE2_V));
310	            SetFlag<HardEvent::MTE2_V>(eventIdMte2ToV);
311	            WaitFlag<HardEvent::MTE2_V>(eventIdMte2ToV);
312	            Cast(dstTensor, tmpTensor, RoundMode::CAST_NONE, pseInfo.vec1S1RealSize * pseInfo.pseS2ComputeSize);
313	        }
314	        return;
315	    }
316	}
