318	template <typename T, bool hasPse>
319	__aicore__ inline void PseSlopeCopyIn(LocalTensor<T> &dstTensor, LocalTensor<half> &helpTensor,
320	                                      __gm__ uint8_t *pseSlope, GlobalTensor<half> &alibiGm, PseInfo &pseInfo,
321	                                      int64_t alignedSize = 16) {
322	    if constexpr (hasPse == true) {
323	        int64_t bOffset = 0;
324	        int64_t n2Offset = pseInfo.n2oIdx * pseInfo.gSize;
325	        int64_t gOffset = pseInfo.goIdx;
326	
327	        if (pseInfo.pseShapeType == PSE_SLOPE_BN) {
328	            bOffset = pseInfo.boIdx * pseInfo.n2G;
329	        }
330	        int64_t offset = bOffset + n2Offset + gOffset;
331	
332	        DataCopyIn<half, hasPse>(helpTensor, alibiGm, 0, pseInfo.vec1S1RealSize,
333	                                 pseInfo.s2RealSize, pseInfo.pseAlibiBaseS2, alignedSize);
334	        event_t eventIdMte2ToV = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE2_V));
335	        SetFlag<HardEvent::MTE2_V>(eventIdMte2ToV);
336	        WaitFlag<HardEvent::MTE2_V>(eventIdMte2ToV);
337	
338	        if (pseInfo.needCast) {
339	            int64_t computeSize = pseInfo.vec1S1RealSize * pseInfo.s2AlignedSize;
340	            Cast(dstTensor, helpTensor, RoundMode::CAST_NONE, computeSize);
341	            AscendC::PipeBarrier<PIPE_V>();
342	
343	            int64_t s1Offset = pseInfo.s1oIdx * pseInfo.s1BaseSize + pseInfo.vecCoreOffset +
344	                               pseInfo.loopIdx * pseInfo.vec1S1BaseSize;
345	            int64_t s2Offset = pseInfo.s2StartIdx + pseInfo.s2LoopCount * pseInfo.s2BaseNratioSize;
346	
347	            float posShift = float(s2Offset + pseInfo.kvStartIdx - s1Offset - pseInfo.qStartIdx);
348	
349	            Adds(dstTensor, dstTensor, posShift, computeSize);
350	            AscendC::PipeBarrier<PIPE_V>();
351	            Abs(dstTensor, dstTensor, computeSize);
352	            AscendC::PipeBarrier<PIPE_V>();
353	            float slopes = ((__gm__ T *)pseSlope)[offset] * -1;
354	            if (pseInfo.pseType == (uint32_t)PseTypeEnum::PSE_INNER_MUL_ADD_SQRT_TYPE) {
355	                Sqrt(dstTensor, dstTensor, computeSize);
356	                AscendC::PipeBarrier<PIPE_V>();
357	            }
358	            Muls(dstTensor, dstTensor, slopes, computeSize);
359	            AscendC::PipeBarrier<PIPE_V>();
360	        }
361	    }
362	}
363	
364	template <typename T, bool hasPse>
365	__aicore__ inline void PseSlopeCast(LocalTensor<T> &dstTensor, LocalTensor<half> &helpTensor,
366	                                    __gm__ uint8_t *pseSlope, PseInfo &pseInfo) {
367	    if constexpr (hasPse == true) {
368	        int64_t bOffset = 0;
369	        int64_t n2Offset = pseInfo.n2oIdx * pseInfo.gSize;
370	        int64_t gOffset = pseInfo.goIdx;
371	
372	        if (pseInfo.pseShapeType == PSE_SLOPE_BN) {
373	            bOffset = pseInfo.boIdx * pseInfo.n2G;
374	        }
375	        int64_t offset = bOffset + n2Offset + gOffset;
376	        int64_t computeSize = pseInfo.vec1S1RealSize * pseInfo.s2AlignedSize;
377	        Cast(dstTensor, helpTensor, RoundMode::CAST_NONE, computeSize);
378	        AscendC::PipeBarrier<PIPE_V>();
379	
380	        int64_t s1Offset = pseInfo.s1oIdx * pseInfo.s1BaseSize + pseInfo.vecCoreOffset +
381	                           pseInfo.loopIdx * pseInfo.vec1S1BaseSize;
382	        int64_t s2Offset = pseInfo.s2StartIdx + pseInfo.s2LoopCount * pseInfo.s2BaseNratioSize;
383	
384	        float posShift = float(s2Offset + pseInfo.kvStartIdx - s1Offset - pseInfo.qStartIdx);
385	
386	        Adds(dstTensor, dstTensor, posShift, computeSize);
387	        AscendC::PipeBarrier<PIPE_V>();
388	        Abs(dstTensor, dstTensor, computeSize);
389	        AscendC::PipeBarrier<PIPE_V>();
390	        float slopes = ((__gm__ T *)pseSlope)[offset] * -1;
391	        if (pseInfo.pseType == (uint32_t)PseTypeEnum::PSE_INNER_MUL_ADD_SQRT_TYPE) {
392	            Sqrt(dstTensor, dstTensor, computeSize);
393	            AscendC::PipeBarrier<PIPE_V>();
394	        }
395	        Muls(dstTensor, dstTensor, slopes, computeSize);
396	        AscendC::PipeBarrier<PIPE_V>();
397	    }
398	}
