400	template <typename INPUT_T, typename T, LayOutTypeEnum layOutType, bool hasPse>
401	__aicore__ inline void PseCopyIn(LocalTensor<T> &dstTensor, LocalTensor<INPUT_T> &tmpTensor,
402	                                 GlobalTensor<INPUT_T> &srcTensor, PseInfo &pseInfo, int64_t alignedSize = 16)
403	{
404	    if constexpr (hasPse == true) {
405	        if (pseInfo.pseEncodeType == pseEncodeALibiS2Full) {
406	            return PseAlibiCopyIn<INPUT_T, T, layOutType, hasPse>(dstTensor, tmpTensor, srcTensor, 
407	                                                                  pseInfo, alignedSize);
408	        }
409	        int64_t offset = PseComputeOffset<hasPse>(pseInfo);
410	        int64_t s1Size = pseInfo.pseShapeType == pse1S2 ? (pseInfo.blockCount == 0 ? 1 : pseInfo.blockCount) :
411	                                                          pseInfo.vec1S1RealSize;
412	
413	        if constexpr (IsSameType<INPUT_T, T>::value) {
414	            if (!pseInfo.align8){
415	                DataCopyIn<INPUT_T, hasPse>(dstTensor, srcTensor, offset, 
416	                                            s1Size, pseInfo.s2RealSize,
417	                                            pseInfo.s2Size, alignedSize);
418	            } else {
419	                DataCopyInAlign8<INPUT_T, hasPse>(dstTensor, srcTensor, 
420	                                                  offset, s1Size, 
421	                                                  pseInfo.s2RealSize, pseInfo.s2Size);
422	            }
423	            return;
424	        }
425	        DataCopyIn<INPUT_T, hasPse>(tmpTensor, srcTensor, offset, s1Size, pseInfo.s2RealSize, pseInfo.s2Size,
426	                                    alignedSize);
427	        if (pseInfo.needCast) {
428	            event_t eventIdMte2ToV = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE2_V));
429	            SetFlag<HardEvent::MTE2_V>(eventIdMte2ToV);
430	            WaitFlag<HardEvent::MTE2_V>(eventIdMte2ToV);
431	            Cast(dstTensor, tmpTensor, RoundMode::CAST_NONE, s1Size * pseInfo.s2AlignedSize);
432	        }
433	        return;
434	    }
435	}
