437	template <typename T, bool hasPse>
438	__aicore__ inline void PseAlibiCompute(LocalTensor<T> &dstTensor, LocalTensor<T> &pseTensor, PseInfo &pseInfo)
439	{
440	    if constexpr (hasPse == true) {
441	        if (!NeedPseAlibiCompute<hasPse>(pseInfo)) {
442	            return;
443	        }
444	        Add(dstTensor, dstTensor, pseTensor, pseInfo.vec1S1RealSize * pseInfo.pseS2ComputeSize);
445	        return;
446	    }
447	}
448	
449	template <typename T, bool hasPse>
450	__aicore__ inline void PseCompute(LocalTensor<T> &dstTensor, LocalTensor<T> &pseTensor, PseInfo &pseInfo)
451	{
452	    if constexpr (hasPse == true) {
453	        if (pseInfo.pseEncodeType == pseEncodeALibiS2Full) {
454	            return PseAlibiCompute<T, hasPse>(dstTensor, pseTensor, pseInfo);
455	        }
456	        int64_t computeSize = (pseInfo.pseShapeType == pseS1S2 || pseInfo.pseShapeType == PSE_SLOPE_BN ||
457	                               pseInfo.pseShapeType == PSE_SLOPE_N)
458	                              ? pseInfo.vec1S1RealSize * pseInfo.s2AlignedSize
459	                              : pseInfo.s2AlignedSize;
460	        PseBroadcastAdd<T, hasPse>(pseInfo.vec1S1RealSize, pseInfo.s2AlignedSize, computeSize, pseTensor,
461	                                   dstTensor, pseInfo.pseShapeType);
462	        return;
463	    }
464	}
465	
466	template <bool hasPse>
467	__aicore__ inline void PseInnerAlibiCreate(GlobalTensor<half> &dstTensor, 
468	                                           LocalTensor<half> &helpTensor, 
469	                                           PseInfo &pseInfo) 
470	{
471	    if constexpr (hasPse == true) {
472	        if (pseInfo.pseType != (uint32_t)PseTypeEnum::PSE_INNER_MUL_ADD_TYPE && 
473	            pseInfo.pseType != (uint32_t)PseTypeEnum::PSE_INNER_MUL_ADD_SQRT_TYPE) {
474	            return;
475	        }
476	        event_t eventIdMte3ToV = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE3_V));
477	        event_t eventIdMte3ToS = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE3_S));
478	        event_t eventIdVToMte3 = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::V_MTE3));
479	        float tmpValue = -1.0;
480	
481	        for (int64_t i = 0; i < pseInfo.pseAlibiBaseS1; i++) {
482	            CreateVecIndex(helpTensor, (half)(i * tmpValue), pseInfo.pseAlibiBaseS2);
483	            SetFlag<HardEvent::V_MTE3>(eventIdVToMte3);
484	            WaitFlag<HardEvent::V_MTE3>(eventIdVToMte3);
485	            DataCopy(dstTensor[i * pseInfo.pseAlibiBaseS2], helpTensor, pseInfo.pseAlibiBaseS2);
486	            SetFlag<HardEvent::MTE3_V>(eventIdMte3ToV);
487	            WaitFlag<HardEvent::MTE3_V>(eventIdMte3ToV);
488	            SetFlag<HardEvent::MTE3_S>(eventIdMte3ToS);
489	            WaitFlag<HardEvent::MTE3_S>(eventIdMte3ToS);
490	        }
491	    }
492	}
