88	__aicore__ inline void BoolCopyIn(LocalTensor<uint8_t> &dstTensor, GlobalTensor<uint8_t> &srcTensor,
89	    int64_t srcOffset, uint32_t s1Size, uint32_t s2Size, int64_t totalS2Size, int64_t alignedSize = blockBytes)
90	{
91	    uint32_t alignedS2Size = CeilDiv(s2Size, alignedSize) * alignedSize;
92	    uint32_t shapeArray[] = {s1Size, alignedS2Size};
93	    dstTensor.SetShapeInfo(ShapeInfo(dim_num, shapeArray, DataFormat::ND));
94	    dstTensor.SetSize(s1Size * alignedS2Size);
95	    DataCopyParams dataCopyParams;
96	    dataCopyParams.blockCount = s1Size;
97	    dataCopyParams.dstStride = 0;
98	    if (totalS2Size == blockBytes && alignedSize == 64) { // totalS2Size < 64 && totalS2Size % blockBytes == 0
99	        dataCopyParams.dstStride = 1;
100	        alignedSize = blockBytes;
101	        alignedS2Size = CeilDiv(s2Size, blockBytes) * blockBytes;
102	    }
103	    if (totalS2Size % alignedSize == 0) {
104	        dataCopyParams.blockLen = alignedS2Size / blockBytes;
105	        dataCopyParams.srcStride = (totalS2Size - alignedS2Size) / blockBytes;
106	        DataCopy(dstTensor, srcTensor[srcOffset], dataCopyParams);
107	    } else {
